mapper.select:
SELECT IFNULL(SUM(credit),0) AS credit, `main_gl_id` AS mainGlId, `chart_account_id` AS chartAccountId, `company_id` AS companyId, `customer_id` AS customerId FROM general_ledgers gl2 INNER JOIN general_ledger_details gld2 ON gl2.id=gld2.general_ledger_id WHERE gl2.is_approve = 1 AND gl2.is_active = 1
AND company_id = #{filter.companyId}
AND customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id= #{filter.groupId})
AND customer_id = #{filter.customerId}
AND chart_account_id IN (SELECT id FROM chart_accounts WHERE is_active=1 AND chart_account_type_id IN (SELECT id FROM chart_account_types WHERE name='Accounts Receivable')) AND sales_order_id IS NULL AND credit_memo_id IS NULL AND purchase_order_id IS NULL AND purchase_return_id IS NULL AND credit>0 GROUP BY `main_gl_id`, `chart_account_id`, `company_id`, `customer_id`

